const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    const tokens = input.trim().split(/\s+/);

    if (tokens.length === 0 || tokens[0] === '') return;

    const n = parseInt(tokens[0], 10);
    let substituidos = 0;
    let consertados = 0;

    for (let i = 1; i <= n; i++) {
        const x = parseInt(tokens[i], 10);
        if (x < 50) {
            substituidos++;
        } else if (x < 85) {
            consertados++;
        }
    }

    console.log(`${substituidos} ${consertados}`);
}

main();
